    68→async function getAccessToken(): Promise<string> {
    69→  const config = getConfig();
    70→  
    71→  // Check if we have a valid cached token
    72→  if (cachedToken && cachedToken.expiresAt > Date.now()) {
    73→    return cachedToken.token;
    74→  }
    75→  
    76→  // Get new token using client credentials
    77→  const tokenUrl = `${config.baseUrl}/auth/open/connect/token`;
    78→  
    79→  const response = await fetch(tokenUrl, {
    80→    method: 'POST',
    81→    headers: {
    82→      'Content-Type': 'application/x-www-form-urlencoded',
    83→      'Authorization': `Basic ${Buffer.from(`${config.clientId}:${config.clientSecret}`).toString('base64')}`,
    84→    },
    85→    body: new URLSearchParams({
    86→      grant_type: 'client_credentials',
    87→      scope: 'signicat-api',
    88→    }),
    89→  });
    90→  
    91→  if (!response.ok) {
    92→    const error = await response.text();
    93→    throw new Error(`Failed to get access token: ${error}`);
    94→  }
    95→  
    96→  const data = await response.json() as { access_token: string; expires_in: number };
    97→  
    98→  // Cache the token (with 5 minute buffer before expiry)
    99→  cachedToken = {
   100→    token: data.access_token,
   101→    expiresAt: Date.now() + (data.expires_in - 300) * 1000,
   102→  };
   103→  
   104→  return data.access_token;
   105→}
