    18→/**
    19→ * Create and configure Fastify app with registered controllers
    20→ */
    21→export async function createFastifyApp(
    22→  controllers: Constructor[],
    23→  options: FastifyAdapterOptions = {}
    24→): Promise<FastifyInstance> {
    25→  const app = Fastify({
    26→    logger: options.logger ?? false,
    27→    requestIdLogLabel: 'correlationId',
    28→  });
    29→
    30→  // Enable CORS for all origins
    31→  await app.register(cors, {
    32→    origin: '*', // Allow ALL origins
    33→    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    34→    allowedHeaders: '*', // Allow ALL headers
    35→  });
    36→
    37→  // Handle empty JSON bodies (fixes SDK sending Content-Type: application/json with no body)
    38→  app.addContentTypeParser('application/json', { parseAs: 'string' }, (req, body, done) => {
    39→    if (!body || body === '') {
    40→      done(null, {});
    41→      return;
    42→    }
    43→    try {
    44→      done(null, JSON.parse(body as string));
    45→    } catch (err) {
    46→      done(err as Error, undefined);
    47→    }
    48→  });
    49→
    50→  // Inject adapters into requests
    51→  if (options.adapters) {
    52→    app.decorateRequest('adapters', null);
    53→    app.decorateRequest('tenantId', null);
    54→    app.decorateRequest('userId', null);
    55→
    56→    app.addHook('onRequest', async (request: any) => {
    57→      request.adapters = options.adapters;
    58→      // Use Skien Kommune as default tenant for demo, or null for public access
    59→      request.tenantId = request.headers['x-tenant-id'] || null;
    60→      request.userId = request.headers['x-user-id'] || null;
    61→    });
    62→  }
    63→
    64→  // Request logging
    65→  if (options.adapters?.log) {
    66→    app.addHook('onRequest', async (request) => {
    67→      options.adapters.log.info('Request received', {
    68→        method: request.method,
    69→        url: request.url,
    70→        correlationId: request.id,
    71→      });
    72→    });
    73→
    74→    app.addHook('onResponse', async (request, reply) => {
    75→      options.adapters.log.info('Request completed', {
    76→        method: request.method,
    77→        url: request.url,
    78→        statusCode: reply.statusCode,
    79→        duration: reply.elapsedTime,
    80→      });
    81→    });
    82→  }
    83→
    84→  // Global error handler (RFC 7807)
    85→  app.setErrorHandler(async (error: Error, request: FastifyRequest, reply: FastifyReply) => {
    86→    options.adapters?.log?.error('Request error', {
    87→      error: error.message,
    88→      stack: error.stack,
    89→      correlationId: request.id,
    90→    });
    91→
    92→    const problemDetails = serializeError(error, request.id);
    93→    return reply
    94→      .status(problemDetails.status)
    95→      .header('Content-Type', 'application/problem+json')
    96→      .send(problemDetails);
    97→  });
    98→
    99→  // Register controllers
   100→  for (const Controller of controllers) {
   101→    await registerController(app, Controller, options.prefix);
   102→  }
   103→
   104→  return app;
   105→}
   106→
   107→/**
   108→ * Register a controller's routes with Fastify
   109→ */
   110→async function registerController(
   111→  app: FastifyInstance,
   112→  Controller: Constructor,
   113→  globalPrefix?: string
   114→): Promise<void> {
   115→  const metadata = getControllerMetadata(Controller);
   116→  const controllerInstance = container.resolve(Controller.name);
   117→  const prefix = joinPaths(globalPrefix, metadata.prefix);
   118→
   119→  for (const route of metadata.routes) {
   120→    const path = joinPaths(prefix, route.path);
   121→    const handler = (controllerInstance as any)[route.handler].bind(controllerInstance);
   122→
   123→    switch (route.method) {
   124→      case 'GET':
   125→        app.get(path, handler);
   126→        break;
   127→      case 'POST':
   128→        app.post(path, handler);
   129→        break;
   130→      case 'PUT':
   131→        app.put(path, handler);
   132→        break;
   133→      case 'PATCH':
   134→        app.patch(path, handler);
   135→        break;
   136→      case 'DELETE':
   137→        app.delete(path, handler);
   138→        break;
   139→    }
   140→  }
   141→}
   142→
   143→/**
   144→ * Join path segments, ensuring result starts with /
   145→ */
   146→function joinPaths(...paths: (string | undefined)[]): string {
   147→  const joined = paths
   148→    .filter(Boolean)
   149→    .map((p) => p!.replace(/^\/+|\/+$/g, ''))
   150→    .filter((p) => p.length > 0)
   151→    .join('/');
   152→  return joined ? `/${joined}` : '/';
   153→}
